<script lang="ts">
 import type {Project} from './model';import {translator} from './i18n';import {displayDate} from './date-format';import {statusLabel,citizenName} from './account-data';import {entryConsumption} from './meter-entry';import {RefreshCw,X} from '@lucide/svelte';
 export let project:Project;export let accountId:string;export let type:string;export let subject='';export let onclose:()=>void;
 function formatEnd(value:string){return /^\d{4}-\d{2}-\d{2}$/.test(value)?displayDate(value,project):value;}
 $:t=translator(project.settings.language);let revision=0;
 $:rows=(()=>{revision;const h=project.account_history,ro=project.settings.language==='ro';
 if(type==='holder')return h.holders.filter(r=>r.account_id===accountId).map(r=>[r.date,r.name||citizenName(project,r.citizen_id),'']);
 if(type==='registration'||type==='residence')return h.residents.filter(r=>r.account_id===accountId&&r.kind===type&&(!subject||r.citizen_id===subject)).map(r=>[r.from,statusLabel(r.status,type,ro),r.to||'']);
 if(type==='services')return h.services.filter(r=>r.account_id===accountId&&(!subject||r.service_id===subject)).map(r=>[r.date,project.services.find(s=>s.id===r.service_id)?.name[project.settings.language]||r.service_id,r.active?t('Подключена','Conectat'):t('Не подключена','Deconectat')]);
 if(type==='additional')return h.additional.filter(r=>r.account_id===accountId&&(!subject||r.property_id===subject)).map(r=>[r.date,project.reference_catalogs.properties?.find(p=>p.id===r.property_id)?.name||r.property_id,r.active?t('Подключён','Conectat'):t('Не подключён','Deconectat')]);
 if(type==='meter-status')return (project.meters.find(m=>m.id===subject)?.status_history||[]).map(r=>[r.date,r.active?t('Подключён','Conectat'):t('Не подключён','Deconectat'),'']);
 if(type==='meter-readings'||type==='meter-consumption'){const values=project.meter_values.filter(v=>v.meter_id===subject).sort((a,b)=>a.reading_date.localeCompare(b.reading_date));return values.map((r,i)=>[r.reading_date,type==='meter-readings'?r.value:entryConsumption(values[i-1]?.value??project.meters.find(m=>m.id===subject)?.initial_value??null,r.value)||'—',r.kind==='initial'?t('Начальное','Inițial'):t('Очередное','Periodic')]);}
 const doc=project.account_documents.find(d=>d.id===subject);if(!doc)return [];return [...h.holders.filter(r=>r.document_id===doc.id).map(r=>[r.date,t('Ответственный','Responsabil'),r.name]),...h.services.filter(r=>r.document_id===doc.id).map(r=>[r.date,project.services.find(s=>s.id===r.service_id)?.name[project.settings.language]||'',r.active?t('Подключена','Conectat'):t('Отключена','Deconectat')]),...h.residents.filter(r=>r.document_id===doc.id).map(r=>[r.date,citizenName(project,r.citizen_id),statusLabel(r.status,r.kind,ro)]),...(doc.balance_rows||[]).map(r=>[doc.date,project.services.find(s=>s.id===r.service_id)?.name[project.settings.language]||'',r.amount]),...(doc.kind==='close'?[[doc.date,t('Лицевой счёт закрыт','Cont închis'),doc.account.number]]:[])];
 })();
</script>
<div class="account-history"><div class="history-top"><span>{subject?project.reference_catalogs.citizens?.find(c=>c.id===subject)?.name||project.meters.find(m=>m.id===subject)?.label||project.accounts.find(a=>a.id===accountId)?.number:project.accounts.find(a=>a.id===accountId)?.number}</span><button class="button secondary" onclick={()=>revision++}><RefreshCw size={15}/>{t('Обновить','Actualizează')}</button></div><table><thead><tr><th>{t('Дата начала','Data începerii')}</th><th>{t('Значение / состояние','Valoare / stare')}</th><th>{type==='registration'||type==='residence'?t('Дата окончания','Data încheierii'):t('Примечание / значение','Notă / valoare')}</th></tr></thead><tbody>{#each rows as row}<tr><td>{displayDate(row[0],project)}</td><td>{row[1]}</td><td>{formatEnd(row[2])}</td></tr>{/each}</tbody></table>{#if !rows.length}<p>{t('Записей истории нет.','Nu există înregistrări în istoric.')}</p>{/if}<footer><button class="button secondary" onclick={onclose}><X size={16}/>{t('Закрыть','Închide')}</button></footer></div>
<style>.account-history{display:flex;flex-direction:column;gap:14px;padding:16px;min-height:100%;box-sizing:border-box}.history-top{display:flex;justify-content:space-between;align-items:center}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:8px}th{background:#80808020}footer{display:flex;justify-content:flex-end;margin-top:auto}</style>
